// Authentic Real Vehicle Photos from Internet matching Mani Auto Counsalting Visiting Card
// 10 Official Categories: Cars, Two Wheelers, JCB/Earth Movers, Tractors, Pickup, Tippers, Trucks, Buses, Vans, Special Vehicles

export const PRESET_CAR = "data:image/jpeg;base64,";

export const PRESET_TWO_WHEELER = "data:image/jpeg;base64,";

export const PRESET_JCB = "data:image/jpeg;base64,";

export const PRESET_TRACTOR = "data:image/jpeg;base64,";

export const PRESET_PICKUP = "data:image/jpeg;base64,";

export const PRESET_TIPPER = "data:image/jpeg;base64,";

export const PRESET_TRUCK = "data:image/jpeg;base64,";

export const PRESET_BUS = "data:image/jpeg;base64,";

export const PRESET_VAN = "data:image/jpeg;base64,";

export const PRESET_SPECIAL_VEHICLE = "data:image/jpeg;base64,";

// Backward compatibility aliases
export const PRESET_SPORTS_BIKE = PRESET_TWO_WHEELER;
export const PRESET_COMMUTER_BIKE = PRESET_TWO_WHEELER;
export const PRESET_SCOOTER = PRESET_TWO_WHEELER;

export const getPresetForType = (type: string, name?: string): string => {
  const t = (type || "").toLowerCase();
  const n = (name || "").toLowerCase();

  if (t.includes("jcb") || t.includes("earth") || n.includes("jcb") || n.includes("excavat") || n.includes("loader")) {
    return PRESET_JCB;
  }
  if (t.includes("tractor") || n.includes("tractor") || n.includes("mahindra 575") || n.includes("swaraj") || n.includes("di")) {
    return PRESET_TRACTOR;
  }
  if (t.includes("pickup") || n.includes("pickup") || n.includes("bolero") || n.includes("camper") || n.includes("d-max")) {
    return PRESET_PICKUP;
  }
  if (t.includes("tipper") || n.includes("tipper") || n.includes("dump")) {
    return PRESET_TIPPER;
  }
  if (t.includes("truck") || n.includes("truck") || n.includes("freight") || n.includes("eicher") || n.includes("leyland") || n.includes("lorry")) {
    return PRESET_TRUCK;
  }
  if (t.includes("bus") || n.includes("bus") || n.includes("volvo") || n.includes("coach") || n.includes("airavat")) {
    return PRESET_BUS;
  }
  if (t.includes("van") || n.includes("van") || n.includes("traveller") || n.includes("winger") || n.includes("omni") || n.includes("eeco")) {
    return PRESET_VAN;
  }
  if (t.includes("special") || t.includes("crane") || n.includes("crane") || n.includes("hydra") || n.includes("escort")) {
    return PRESET_SPECIAL_VEHICLE;
  }
  if (t.includes("two") || t.includes("bike") || t.includes("motorcycle") || t.includes("scooter") || n.includes("pulsar") || n.includes("duke") || n.includes("splendor")) {
    return PRESET_TWO_WHEELER;
  }
  // Default to clean white car sedan
  return PRESET_CAR;
};
